// src/lib/mcp/tools/list-products.ts
var list_products_default = defineTool2({
  name: "list_products",
  title: "Lister les produits",
  description: "Liste les produits de la boutique avec leur prix, stock et statut. Un filtre texte optionnel permet de chercher par nom ou cat\xE9gorie.",
  inputSchema: {
    search: z.string().optional().describe("Filtre texte sur le nom ou la cat\xE9gorie."),
    limit: z.number().int().optional().describe("Nombre maximum de produits retourn\xE9s (d\xE9faut 20).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ search, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Non authentifi\xE9" }], isError: true };
    }
    const term = search?.trim().toLowerCase();
    const items = mockProducts.filter(
      (p) => !term ? true : `${p.name ?? ""} ${p.category ?? ""}`.toLowerCase().includes(term)
    ).slice(0, Math.max(1, Math.min(limit ?? 20, 100)));
    return {
      content: [{ type: "text", text: JSON.stringify(items) }],
      structuredContent: { count: items.length, products: items }
    };
  }
});

