import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
var list_orders_default = defineTool3({
  name: "list_orders",
  title: "Lister les commandes",
  description: "Liste les commandes de la boutique avec le client, le montant et le statut. Un filtre de statut optionnel est disponible.",
  inputSchema: {
    status: z2.string().optional().describe("Filtre exact sur le statut de la commande."),
    limit: z2.number().int().optional().describe("Nombre maximum de commandes retourn\xE9es (d\xE9faut 20).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ status, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Non authentifi\xE9" }], isError: true };
    }
    const wanted = status?.trim().toLowerCase();
    const items = mockOrders.filter((o) => !wanted ? true : String(o.status ?? "").toLowerCase() === wanted).slice(0, Math.max(1, Math.min(limit ?? 20, 100)));
    return {
      content: [{ type: "text", text: JSON.stringify(items) }],
      structuredContent: { count: items.length, orders: items }
    };
  }
});

